WITH sales_daily AS (SELECT cs_call_center_sk, cs_sold_date_sk AS date_sk, SUM(cs_net_paid) AS sales_amount FROM catalog_sales GROUP BY cs_call_center_sk, cs_sold_date_sk), returns_daily AS (SELECT cr_call_center_sk, cr_returned_date_sk AS date_sk, SUM(cr_return_amount) AS return_amount FROM catalog_returns GROUP BY cr_call_center_sk, cr_returned_date_sk), daily_metrics AS (SELECT COALESCE(s.cs_call_center_sk, r.cr_call_center_sk) AS call_center_sk, COALESCE(s.date_sk, r.date_sk) AS date_sk, COALESCE(s.sales_amount,0) AS sales_amount, COALESCE(r.return_amount,0) AS return_amount FROM sales_daily s FULL OUTER JOIN returns_daily r ON s.cs_call_center_sk = r.cr_call_center_sk AND s.date_sk = r.date_sk) SELECT cc.cc_name, dm.date_sk, dm.sales_amount, dm.return_amount, dm.sales_amount - dm.return_amount AS net_amount, ROUND(100.0 * dm.return_amount / NULLIF(dm.sales_amount,0),2) AS return_pct, CASE WHEN dm.return_amount > dm.sales_amount * 0.25 THEN 'Alert: High Returns' ELSE 'OK' END AS return_status, SUM(dm.sales_amount - dm.return_amount) OVER (PARTITION BY cc.cc_name ORDER BY dm.date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_amount, RANK() OVER (PARTITION BY cc.cc_name ORDER BY (dm.sales_amount - dm.return_amount) DESC) AS day_rank_by_net FROM daily_metrics dm JOIN call_center cc ON dm.call_center_sk = cc.cc_call_center_sk WHERE dm.date_sk IS NOT NULL ORDER BY cc.cc_name, day_rank_by_net LIMIT 50
